INSERT INTO training_quizzes (title, title_ar, description, description_ar, passing_score) VALUES
('Business Terminology Quiz', 'اختبار المصطلحات التجارية', 'Test your knowledge of business service terminology', 'اختبر معرفتك بمصطلحات الخدمات التجارية', 70);

SET @quiz3_id = LAST_INSERT_ID();

-- Question 1
INSERT INTO quiz_questions (quiz_id, question, question_ar, correct_answer, explanation, explanation_ar, order_index) VALUES
(@quiz3_id, 'What is the correct translation for "Booking"?', 'ما هي الترجمة الصحيحة لـ "Booking"؟', 'حجز', 'حجز is the standard term for booking in business context', 'حجز هو المصطلح القياسي للحجز في السياق التجاري', 0);

SET @q1_id = LAST_INSERT_ID();

INSERT INTO quiz_options (question_id, option_text, option_text_ar, is_correct, order_index) VALUES
(@q1_id, 'موعد', 'موعد', FALSE, 0),
(@q1_id, 'حجز', 'حجز', TRUE, 1),
(@q1_id, 'طلب', 'طلب', FALSE, 2),
(@q1_id, 'تسجيل', 'تسجيل', FALSE, 3);

-- Question 2
INSERT INTO quiz_questions (quiz_id, question, question_ar, correct_answer, explanation, explanation_ar, order_index) VALUES
(@quiz3_id, 'What status term means "Pending"?', 'ما مصطلح الحالة الذي يعني "Pending"؟', 'قيد الانتظار', 'قيد الانتظار is the formal term for pending status', 'قيد الانتظار هو المصطلح الرسمي لحالة الانتظار', 1);

SET @q2_id = LAST_INSERT_ID();

INSERT INTO quiz_options (question_id, option_text, option_text_ar, is_correct, order_index) VALUES
(@q2_id, 'منتظر', 'منتظر', FALSE, 0),
(@q2_id, 'قيد الانتظار', 'قيد الانتظار', TRUE, 1),
(@q2_id, 'غير مكتمل', 'غير مكتمل', FALSE, 2),
(@q2_id, 'تحت المراجعة', 'تحت المراجعة', FALSE, 3);

-- Question 3
INSERT INTO quiz_questions (quiz_id, question, question_ar, correct_answer, explanation, explanation_ar, order_index) VALUES
(@quiz3_id, 'How should button text be formatted in Arabic?', 'كيف يجب تنسيق نص الأزرار بالعربية؟', 'Concise, 1-2 words, imperative form', 'Button text should be brief and use command form (e.g., احجز not الحجز)', 'يجب أن يكون نص الزر موجزاً ويستخدم صيغة الأمر (مثل احجز وليس الحجز)', 2);

SET @q3_id = LAST_INSERT_ID();

INSERT INTO quiz_options (question_id, option_text, option_text_ar, is_correct, order_index) VALUES
(@q3_id, 'Long descriptive sentences', 'جمل وصفية طويلة', FALSE, 0),
(@q3_id, 'Concise, 1-2 words, imperative form', 'موجز، 1-2 كلمة، صيغة الأمر', TRUE, 1),
(@q3_id, 'Full formal phrases', 'عبارات رسمية كاملة', FALSE, 2),
(@q3_id, 'English text only', 'نص إنجليزي فقط', FALSE, 3)

